/**
 * The chart's canvas icons (LUCIDE_PATHS, generated by scripts/gen-check-icons.mjs)
 * must draw exactly what the React icons draw (grids, panels, prints) — spec §8.5.
 * Each React icon is rendered with react-dom/server and its shapes compared with
 * the generated paths, so a lucide-react bump that changes an icon fails here
 * until the generator is re-run.
 */
import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, it } from "vitest";
import { CHECK_ICONS, ICON_KEYS, type IconKey } from "@/components/readiness/icon-registry";
import { LUCIDE_PATHS, buildCheckSvg } from "@/lib/check-icon-svg";

/** Hand-drawn, not lucide: the generator leaves it as written. */
const HAND_DRAWN: readonly IconKey[] = ["rotary-table"];

// The generator's allow-list: only geometry reaches the SVG the chart embeds.
const TAGS = new Set(["path", "circle", "rect", "line", "polyline", "polygon", "ellipse"]);
const ATTRS = new Set([
  "d", "cx", "cy", "r", "rx", "ry", "x", "y", "x1", "y1", "x2", "y2", "width", "height", "points",
]);

interface Shape {
  tag: string;
  attrs: Record<string, string>;
}

/** An SVG document's drawn elements, in draw order, with their attributes. */
function shapes(markup: string): Shape[] {
  const doc = new DOMParser().parseFromString(markup, "image/svg+xml");
  if (doc.getElementsByTagName("parsererror").length > 0) {
    throw new Error(`not well-formed SVG: ${markup.slice(0, 120)}`);
  }
  expect(doc.documentElement.tagName).toBe("svg");
  return Array.from(doc.documentElement.children).map((el) => ({
    tag: el.tagName,
    attrs: Object.fromEntries(Array.from(el.attributes).map((a) => [a.name, a.value])),
  }));
}

const reactShapes = (key: IconKey) =>
  shapes(renderToStaticMarkup(createElement(CHECK_ICONS[key])));
const canvasShapes = (key: IconKey) => shapes(buildCheckSvg(key, "Completed"));

const LUCIDE_BACKED = ICON_KEYS.filter((key) => !HAND_DRAWN.includes(key));

describe("generated icon paths", () => {
  it("has 68 keys, written in registry order", () => {
    expect(ICON_KEYS).toHaveLength(68);
    expect(Object.keys(LUCIDE_PATHS)).toEqual([...ICON_KEYS]);
  });

  it.each(LUCIDE_BACKED)("%s draws on the canvas exactly what its React icon draws", (key) => {
    const canvas = canvasShapes(key);
    expect(canvas.length).toBeGreaterThan(0);
    expect(canvas).toEqual(reactShapes(key));
  });

  it("keeps the hand-drawn rotary table's canvas and React twins identical", () => {
    expect(canvasShapes("rotary-table")).toEqual(reactShapes("rotary-table"));
  });

  it("embeds only allow-listed geometry (no scripts, links or handlers)", () => {
    for (const key of ICON_KEYS) {
      for (const shape of canvasShapes(key)) {
        expect(TAGS, `${key}: <${shape.tag}>`).toContain(shape.tag);
        for (const attr of Object.keys(shape.attrs)) {
          expect(ATTRS, `${key}: ${attr} on <${shape.tag}>`).toContain(attr);
        }
      }
    }
  });

  it("redraws LOC, FE and FID with lucide 0.577's shapes (the React icons')", () => {
    // Before phase 7 the canvas kept older lucide paths for these three gates.
    expect(LUCIDE_PATHS["map-pin"]).not.toContain("M20 10c0 6-8 12-8 12");
    expect(LUCIDE_PATHS["drafting-compass"]).not.toContain("M19 12c-3.87 4-10.13 4-14 0");
    expect(LUCIDE_PATHS.gavel).not.toContain("m14.5 12.5-8 8");
  });
});
